from copy import deepcopy
from estilo_tecnico import img,table

def apply(old):
 d={s['title']:deepcopy(s) for s in old};out=[]
 def take(key,title=None,body=None,kind='',chapter=None):
  s=deepcopy(d[key]);s['title']=title or key
  if body is not None:s['body']=body
  s['kind']=kind
  if chapter:s['chapter']=chapter
  out.append(s);return s
 def para(t):return '<p class="prose">'+t+'</p>'
 def caption(t):return '<p class="caption">'+t+'</p>'
 def pair(left,right):return '<div class="editorial-pair"><div>'+left+'</div><div>'+right+'</div></div>'
 take('Predicción multimodal de<br>atención y activación','¿Qué aporta el historial<br>a la predicción de atención<br>y activación?', '<p class="cover-sub">Desarrollo y revisión de modelos multimodales<br>durante la navegación web</p><div class="byline"><b>Mario</b><span>Magíster en Ciencia de Datos<br>Avance de tesis · noviembre de 2026</span></div>','story-cover','TESIS MDS / AVANCE EXPERIMENTAL')
 take('Problema y objetivo de investigación','La pregunta inicial',pair('<p class="opening">Una ventana muestra<br>un momento.<br><span>El historial permite<br>observar cambios.</span></p>', '<h3>Lo que quería contrastar</h3>'+para('Si un modelo que incorpora ventanas anteriores predice mejor que uno que recibe solo la ventana actual.')+para('La hipótesis exige esa mejora en atención y activación.')),chapter='01 / DISEÑO DE LA INVESTIGACIÓN')
 take('Arquitectura profesor–estudiante','Antes de entrenar, había que definir qué predecir', '<p class="intro">Los registros contienen señales, pero no una etiqueta directa de atención o activación.</p>'+table(['Objetivo','Construcción de la etiqueta','Señales para predecirla'],[['Atención','Mirada + pupila','EEG + GSR'],['Activación','GSR','EEG + mirada + pupila']])+caption('Las señales usadas para construir una etiqueta se excluyen de los predictores de esa tarea.'),chapter='01 / DISEÑO DE LA INVESTIGACIÓN')
 take('Particiones y unidad de evaluación','La evaluación quedó separada por persona','<div class="split-counts"><div><b>25</b><span>Entrenamiento</span></div><div><b>8</b><span>Validación</span></div><div><b>8</b><span>Test</span></div></div><div class="method-line"><span><b>2 s</b> por ventana</span><span><b>1 s</b> de desplazamiento</span><span><b>41</b> personas en el análisis principal</span></div>'+caption('Las ventanas solapadas no se tratan como participantes independientes. Validación y test tienen exposición histórica.'),chapter='01 / DISEÑO DE LA INVESTIGACIÓN')
 take('Modelos y controles evaluados','Primero comparé modelos y formas de usar el historial',table(['Etapa','Qué se evaluó','Qué debía controlar'],[['Baselines','Logística y modelos de árboles','Referencia con ventana actual'],['Redes temporales','TCN, LSTM y BiLSTM','Aporte del historial frente a la arquitectura'],['Fusión','Combinaciones de modalidades','Ganancia respecto de sensores individuales']])+caption('Septiembre de 2026. Los objetivos y etiquetas de esta etapa difieren de la versión corregida actual.'),chapter='02 / PRIMEROS EXPERIMENTOS')
 take('Extracción EEG por canal','Después reconstruí atención y recuperé el EEG por canal',pair('<h3>La etiqueta</h3>'+para('Recalculé el profesor de atención desde las características de mirada y pupila.')+para('Comparé una combinación igualitaria con PCA, ajustado dentro de cada fold.'),'<h3>Los predictores</h3><p class="feature-count">16 <span>canales</span></p>'+para('La extracción incorporó 342 entradas EEG nuevas, en lugar de resumir todos los canales.') )+caption('Octubre de 2026. Datos crudos recuperados y extracción alineada con las ventanas originales.'),chapter='03 / RECONSTRUCCIÓN DE ATENCIÓN')['source']+='; resultados/profesor_binario_reconstruido_29-10-2026/INFORME.md'
 take('Atención: comparación controlada','El resultado de atención llegó a 0,6744',pair('<div class="result-number">0,6744</div><p class="metric-label">AUC test · CatBoost estático</p><p class="secondary-number">0,6798 <span>en validación</span></p>','<h3>Qué representa este resultado</h3>'+para('Discriminación de las pseudoetiquetas de atención en ocho personas de test.')+para('Para evaluar la temporalidad, faltaba comparar el historial con un estático equivalente.')),'result-slide','03 / RESULTADOS DE ATENCIÓN')
 take('Atención: comparación controlada','El historial subió la AUC de 0,6602 a 0,6879',table(['HistGradientBoosting · test','AUC','IC95% descriptivo'],[['Ventana actual','0,6602','[0,6139; 0,7043]'],['Historial hasta 32 ventanas','0,6879','[0,6434; 0,7304]']])+'<div class="contrast-line"><strong>+0,0277</strong><span>ΔAUC<br>IC95% [−0,0041; +0,0505]</span><p>Mejora en 7 de 8 personas.<br>El intervalo incluye cero.</p></div>',chapter='03 / RESULTADOS DE ATENCIÓN')
 take('Atención: sensibilidad a la representación','La representación también cambió el resultado',img('contrastes_atencion','Dos experimentos sobre el test histórico. IC95% bootstrap pareados; resultados exploratorios.') ,chapter='03 / RESULTADOS DE ATENCIÓN')
 take('Diagnóstico de las etiquetas GSR originales','En activación aparecieron problemas con las etiquetas',pair('<p class="person-id">P4</p><p class="opening">Solo el <b>12,6%</b><br>de sus ventanas<br>tenía GSR válido.</p>','<h3>Sin embargo, todas recibían etiqueta</h3>'+para('También aparecieron empates, clases desbalanceadas y poco historial completo.')+para('La prioridad pasó a ser auditar el objetivo antes de seguir ajustando modelos.')),chapter='04 / REVISIÓN DE ACTIVACIÓN')
 take('Error de alineación en el generador histórico','La auditoría confirmó un error de índices', '<p class="intro">Al agrupar por participante y reiniciar los índices,<br>los componentes GSR se asignaban a otras ventanas.</p><div class="audit-layout"><div><b>25.498</b><span>posiciones desplazadas<br>de 25.992 en el archivo completo</span></div><div><p>El cálculo con ese error reprodujo<br>los scores históricos guardados.</p><p>Los AUC de activación basados en esas<br>etiquetas dejaron de ser evidencia válida.</p></div></div>'+caption('La cifra cuenta posiciones de componentes, no etiquetas binarias que cambiaron.'),chapter='04 / REVISIÓN DE ACTIVACIÓN')
 take('Criterios de calidad de GSR V2','Reconstruí las etiquetas conservando cada ventana',table(['Paso','Regla de GSR V2'],[['1 · Calidad','Cobertura ≥50%; cuatro componentes finitos; SCR no negativos'],['2 · Normalización','Solo ventanas válidas; identidad e índices conservados'],['3 · Contexto','Cinco ventanas consecutivas válidas para el score de 6 s'],['4 · Clase','Mediana personal; empates y scores constantes sin etiqueta']])+caption('El contexto se reinicia ante huecos o cambios de estímulo. La etiqueta sigue siendo relativa a la sesión y offline.'),chapter='04 / ETIQUETAS GSR V2')
 take('GSR V2: retención de ventanas','La corrección dejó 11.796 ventanas etiquetables',img('retencion','Se conserva el 53,1% de las ventanas principales. La mayor exclusión se debe a historial insuficiente, no a mala señal GSR.'),chapter='04 / ETIQUETAS GSR V2')
 take('Activación V2: protocolo de entrenamiento','Volví a entrenar con las mismas filas en cada comparación',table(['Decisión','Configuración'],[['Modelo','HistGradientBoosting; contexto actual, hasta 8 y hasta 32'],['Selección en train','5 folds por participante; 30 ajustes internos'],['Configuración compartida','15 hojas · 300 iteraciones · learning rate 0,05 · L2 = 10'],['Evaluación','15 modelos OOF y 3 finales; mismos participantes y etiquetas']])+caption('El recálculo reprodujo exactamente la ejecución V2 previa. La auditoría comprobó 123 AUC individuales y 21 recargas predictivas.'),chapter='05 / RECÁLCULO DE ACTIVACIÓN')['source']+='; resultados/activacion_gsr_v2_recalculo_02-11-2026/auditoria_desde_disco.json'
 take('Activación V2: AUC e intervalos de confianza','Con GSR V2, las AUC quedaron cerca de 0,50',img('auc_activacion','HistGradientBoosting · media por participante e IC95% descriptivos. Referencia aleatoria: 0,50.'),chapter='05 / RECÁLCULO DE ACTIVACIÓN')
 take('Activación V2: contrastes temporales pareados','La mejora con 8 ventanas en test no se repitió en validación',img('contrastes_activacion','Diferencias pareadas temporal − estático. Principal: hasta 32 ventanas. Secundario: hasta 8.'),chapter='05 / RECÁLCULO DE ACTIVACIÓN')
 take('Cobertura efectiva del historial','Además, casi nunca había un historial largo disponible',img('historial','Contexto 32 en test: 8,73 ventanas de media y ninguna secuencia completa. Los cortes de segmento y calidad limitan el historial.'),chapter='05 / COBERTURA TEMPORAL')
 take('Activación V2: ablación de modalidades','Combinar modalidades tampoco mostró una ventaja clara',img('ablaciones','Activación V2 · test. Los nueve IC pareados de fusión menos modalidad individual incluyen cero.'),chapter='05 / ABLACIÓN DE MODALIDADES')
 take('Interpretación de la hipótesis','Atención y activación dejan resultados distintos',table(['','Atención','Activación GSR V2'],[['Resultado','AUC alrededor de 0,67–0,69','AUC test entre 0,51 y 0,55'],['Temporalidad','Mejoras exploratorias en algunos contrastes','Mejora secundaria en test, sin réplica en validación'],['Estado','Evidencia favorable, aún exploratoria','Contraste principal inconcluso']])+caption('La superioridad temporal conjunta sigue sin quedar demostrada. Los resultados no descartan cualquier posible aporte temporal.'),chapter='06 / INTERPRETACIÓN')
 take('Conclusiones y trabajo pendiente','La siguiente decisión es cómo cerrar la evaluación', '<div class="next-decision"><h3>Qué quedó resuelto</h3>'+para('La alineación de las etiquetas, el recálculo y la trazabilidad de los resultados.')+'<h3>Qué falta definir</h3>'+para('El efecto mínimo relevante, el alcance de la hipótesis y la factibilidad de una evaluación independiente.')+'<h3>Para discutir con el profesor</h3>'+para('Si el cierre se limita al experimento actual o se plantea una nueva cohorte con un contraste predefinido.')+'</div>',chapter='06 / DISCUSIÓN')
 # Reference material stays available without interrupting the account.
 for key,title in [('Atención: curvas ROC en test','ROC de atención'),('Activación V2: curvas ROC en test','ROC de activación GSR V2'),('Modalidades y características','Señales y características utilizadas'),('Definición de la métrica ROC-AUC','Cómo se calculó la AUC'),('Protocolo de evaluación prospectiva','Regla de decisión propuesta'),('Sensibilidad del tamaño de muestra','Escenarios de tamaño de muestra'),('Referencias y trazabilidad','Fuentes y resultados reproducibles')]:
  s=take(key,title,chapter='ANEXO / DETALLE METODOLÓGICO');s['body']=s['body'].replace('class="technical-note"','class="caption"')
 return out

